# Revised understanding:
# For each cell at column c:
# - If it contains a special color (9), keep it unchanged
# - Otherwise, find if there's a special cell BEFORE and AFTER this cell in the same row
#   - If yes (this cell is between two specials), fill it based on parity:
#     - If c % 2 == 1 (odd), fill with 2
#     - If c % 2 == 0 (even), keep background 6
#   - If no (before first or after last special), keep as background 6

output = []
for r in range(14):
    nines_positions = [c for c in range(15) if grid[r][c] == 9]

    if not nines_positions:
        output.append(grid[r][:])
        continue

    new_row = []
    for c in range(15):
        if grid[r][c] == 9:
            new_row.append(9)
        else:
            # Check if this cell is between first and last special
            if min(nines_positions) < c < max(nines_positions):
                # Cell is between specials, apply parity rule
                if c % 2 == 1:
                    new_row.append(2)
                else:
                    new_row.append(6)
            else:
                # Before first or after last special
                new_row.append(6)

    output.append(new_row)

print("Computed output:")
for r in range(14):
    print(f"Row {r}: {' '.join(str(x) for x in output[r])}")
